# -*- coding: utf-8 -*-
from pathlib import Path
import json
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
Q=[['拉丁 quintus / quinta','第五；quinta 为阴性形式']]
QE=Q+[['中世纪拉丁 quinta essentia','第五元素：古代关于天界精纯物质的观念'],['法语 quinte essence／直接拉丁借入 → 英语 quintessence','第五元素 → 最纯粹的本质、典型体现']]
QA=QE+[['英语 quintessence + -al → quintessential','集中体现某种本质或特征的']]
W=[E('quintessential','/ˌkwɪntɪˈsenʃəl/','最典型的；集中体现本质的','一看这个例子，就知道这一类东西是什么样。','英语 quintessence + -al。quintessence 原是“第五元素”，后来指精髓；形容词便发展成“把核心特征表现得最充分的”。不要把它误拆为 quint- 加现代 essential“必不可少的”。',QA,'A quintessential detective story 是把侦探故事的典型特点表现得很充分的作品，不是“第五篇侦探故事”。这个词重在代表性，未必意味着道德高尚或品质最好。','a quintessential example；the quintessential outsider；a quintessential detective story。','typical 可以只是常见、一般；quintessential 更强调“这简直就是这一类的代表”，语气较强，也更正式。',('The locked room and hidden clues make this a quintessential detective story.','密室和隐藏线索让它成为一部十分典型的侦探故事。'),('For him, a picnic beside the lake was the quintessential summer experience.','对他来说，湖边野餐最能体现夏天的滋味。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/quintessential','https://www.etymonline.com/word/quintessential']),
E('quintessentially','/ˌkwɪntɪˈsenʃəli/','极具代表性地；典型地','强调某种风格从里到外都很有辨识度。','英语 quintessential + -ly，沿“精髓 → 最典型的 → 典型地”形成副词。-ly 改变词在句中的作用，核心意义不变。',QA+[['英语 quintessential + -ly','用副词说明某种性质特别典型']],'它常放在形容词前，例如 quintessentially modern，意思是非常能代表现代风格。也能直接接人名代词：That is quintessentially her，表示那种做法真有她的特点。','quintessentially modern；quintessentially urban；quintessentially human。','essentially 常指“本质上、基本上”；quintessentially 强调典型风格，不能在所有句子中互换。',('The building is quintessentially modern, with open spaces and clean lines.','这座建筑有开阔空间和简洁线条，极具现代风格。'),('Her habit of turning every problem into a sketch is quintessentially her.','她遇到问题就画草图的习惯，真是她一贯的风格。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/quintessentially','https://en.wiktionary.org/wiki/quintessentially']),
E('quintessence','/kwɪnˈtesəns/','精髓；最典型的体现；第五元素〔历史概念〕','把一件事最有代表性的部分，想象成提炼出来的精华。','经法语 quinte essence 或直接接中世纪拉丁 quinta essentia“第五元素”。quinta 是第五，essentia 是本质、存在；这里来自古代哲学与炼金术观念，不是现代化学的第五号元素。',QE,'古人把土、水、气、火之外的天界物质设想为更精纯的第五元素。英语后来借这个形象说“最纯粹的本质”。The quintessence of patience 是耐心的典型体现，不是计算耐心有五份。','the quintessence of something；capture the quintessence of a place；the quintessence of elegance。','essence 可以泛指本质；quintessence 往往带“最浓缩、最典型”的强调。现代科学中的同名专业概念另有具体定义，不能拿古代元素观直接解释。',('That single photograph captures the quintessence of village life.','那一张照片就抓住了乡村生活的精髓。'),('To the children, their grandmother was the quintessence of patience.','在孩子们眼里，奶奶就是耐心的化身。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/quintessence','https://www.etymonline.com/word/quintessence']),
E('quintile','/ˈkwɪntaɪl/','五分位数；五等分组中的一组','把人或数据排好队，再按数量分成五组。','quint- 接拉丁 quintus“第五”，加 -ile，构形也与 quartile 呼应。这个形式早先用于占星的五分之一圆周，后来进入统计语言；现代统计含义不需要占星背景。',Q+[['英语 quintile：quint- + -ile','早期五分之一圆周的占星用词'],['现代统计 quintile','五等分的分界值，或分成的五组之一']],'按收入把一百户家庭从低到高排序，分成每组二十户，最高一组就是 top income quintile。每组户数相同，不意味着每组总收入相同。严格说，分成五组需要四个内部界值；日常统计报道也把组本身叫 quintile。','income quintile；the top/bottom quintile；divide the sample into quintiles。编号方向要看报告，不如 top/bottom 直接。','quartile 分四组，quintile 分五组，decile 分十组；它们先按所研究的变量排序，再讨论位置。',('The chart compares household spending across five income quintiles.','图表比较了五个收入组的家庭支出。'),('Each quintile contains twenty of the one hundred households in our example.','在我们的例子中，一百户家庭的每个五分位组都包含二十户。'),sources=['https://www.merriam-webster.com/dictionary/quintile','https://www.oxfordlearnersdictionaries.com/definition/english/quintile','https://www.etymonline.com/word/quintile']),
E('quintet','/kwɪnˈtet/','五重奏；五人乐组；五个一组','五个演奏者各有声部，一起完成音乐。','由法语 quintette 或意大利语 quintetto 借入。意大利 quinto“第五”接小称后缀形成 quintetto，远接拉丁 quintus；英语先用于五声部作品，后来也指演奏这种作品的五人组合。',Q+[['意大利 quinto → quintetto','第五 → 五重奏作品'],['意大利直接借入／法语 quintette 中介 → 英语 quintet','五重奏；五人乐组，也可泛指五个一组']],'看动词就容易判断：a quintet performs 是五人乐组在演奏；write a quintet 是写一部五重奏作品。五件乐器不要求都是同一种，具体配置要看作品。','a jazz quintet；a string quintet；a piano quintet；a quintet of musicians。','quartet 是四重奏，quintet 是五重奏。quintet 说一组的成员数量，不是第五乐章。',('The quintet rehearsed in a small room above the café.','五人乐组在咖啡馆楼上的小房间里排练。'),('She wrote a quintet for flute and four string instruments.','她为长笛和四件弦乐器写了一部五重奏。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/quintet','https://www.etymonline.com/word/quintet']),
E('quintuple','英 /ˈkwɪntjʊpəl/；美 /kwɪnˈtuːpəl/','使增至五倍；增至五倍；五倍的；由五部分组成的','原来一份，现在变成五份。','经法语 quintuple 接中世纪拉丁 quintuplus：quintus“第五”加表示倍数的 -plus，与 duplus“二倍”一类形式对应。英语形容词也转作动词，表示变成五倍。',Q+[['中世纪拉丁 quintuplus → 法语 quintuple','五倍的'],['英语 quintuple','五倍的、五部分的；转作使增至五倍的动词']],'Quintuple the capacity 是把容量变成原来的五倍。若从十升变成五十升，就是 quintuple；增加量是四十升，别误算成原量再加五倍。它也能说由五个部分构成的事物。','quintuple output/capacity；costs quintuple；quintuple the original amount。','fivefold 常作形容词或副词，quintuple 还可以直接作动词。两者表达“五倍”时，都要区分最终总量和增加量。',('The redesign could quintuple the number of items stored in each cabinet.','重新设计后，每个柜子能存放的物品数量可增至原来的五倍。'),('Membership quintupled from twenty to one hundred.','会员人数从二十人增至一百人，变成原来的五倍。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/quintuple_1','https://www.oxfordlearnersdictionaries.com/definition/english/quintuple_2'])]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());r=next(x for x in m['roots']if x['id']=='C1195');c=next(x for x in json.loads((BASE/'.cache/catalog.json').read_text())if x['id']=='C1195');keep={w['word']for w in W};excluded={w:'按用户当前范围暂略：少见简称、专业数学或占星术语、古词与罕见派生。'for w in(set(r['family'])|set(c['family'])|set(c.get('unmatched',[])))-keep};excluded['quintal']='重量单位经阿拉伯语 qintar，远接拉丁 centenarius“百”；不是 quintus“第五”词族，勿因外形相似误归。'
ROOT=[dict(id='C1195',meaning='第五；五个、五倍',core='quint- 抓住数量“五”，有时还保留顺序“第五”。',image='五个人组成 quintet；把队列分成五组得到 quintiles；古代的第五元素又引出“精髓”。',intro='这组有两条好记的路线：数量义进入音乐与统计；古代第五元素的观念转成 quintessence“精髓”和 quintessential“最典型的”。',forms='拉丁 quintus“第五”，阴性 quinta → quint-。与 quinque“五”相关；并非所有 quint 开头的词都来自这条路线。',branches=[['精髓与典型风格','quintessence、quintessential、quintessentially'],['五组、五人、五倍','quintile、quintet、quintuple']],contrasts='quintessential 不是“第五个重要的”；quintile 等分的是排序后的人数或条目数。quintal 重量单位另源。',practice='把 quintet、quintile、quintuple 分别对应五人、五组、五倍，再解释“第五元素”怎样转成“精髓”。',words=[w for w in r['family']if w in keep],exclude=excluded,sources=['https://www.etymonline.com/word/quintessence','https://www.etymonline.com/word/quintet','https://www.etymonline.com/word/quintal'])]
assert all(w['word']in m['owned_words']for w in W)
assert not(set(c['family'])|set(c.get('unmatched',[])))-set(ROOT[0]['words'])-set(excluded)
for w in W:assert len(w['examples'])>=2 and all(len(n)==2 and all(isinstance(x,str)and x for x in n)for n in w['history'])
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_210_quint.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('C1195',len(W),'new',len(ROOT[0]['words']),'retained')
